-- Historical constraint definitions observed in the read-only production dump on 2026-10-24.
-- The out-of-order grant migration predates the current scoped/trial definitions.
ALTER TABLE organization_entitlements DROP CONSTRAINT organization_entitlements_plan_state_check;
ALTER TABLE organization_entitlements ADD CONSTRAINT organization_entitlements_plan_state_check CHECK ((((source_grant_id IS NULL) AND ((plan_key = ANY (ARRAY['free'::text, 'plus_monthly'::text, 'pro_monthly'::text])) AND (state = ANY (ARRAY['free'::text, 'active'::text, 'grace'::text, 'past_due'::text, 'unpaid'::text])) AND (((plan_key = 'free'::text) AND (state = 'free'::text) AND entitlement_effective AND ((source_subscription_id IS NULL) = (source_subscription_revision IS NULL))) OR ((plan_key <> 'free'::text) AND (state <> 'free'::text) AND (source_subscription_id IS NOT NULL) AND (source_subscription_revision IS NOT NULL) AND (entitlement_effective = (state = ANY (ARRAY['active'::text, 'grace'::text]))))))) OR ((source_grant_id IS NOT NULL) AND (plan_key = ANY (ARRAY['plus_monthly'::text, 'pro_monthly'::text])) AND (state = 'active'::text) AND entitlement_effective AND (source_subscription_id IS NULL) AND (source_subscription_revision IS NULL) AND (effective_until IS NOT NULL))));
ALTER TABLE subscription_allowance_periods DROP CONSTRAINT subscription_allowance_periods_invoice_id_check;
ALTER TABLE subscription_allowance_periods ADD CONSTRAINT subscription_allowance_periods_invoice_id_check CHECK ((((grant_source = 'paid_invoice'::text) AND (provider = 'stripe'::text) AND (provider_environment = ANY (ARRAY['test'::text, 'live'::text])) AND (subscription_id IS NOT NULL) AND (subscription_revision IS NOT NULL) AND (stripe_invoice_id IS NOT NULL) AND (stripe_invoice_id ~ '^in_[A-Za-z0-9]+$'::text) AND (promo_grant_id IS NULL)) OR ((grant_source = 'promo_grant'::text) AND (provider = 'eliza'::text) AND (provider_environment = ANY (ARRAY['test'::text, 'live'::text])) AND (subscription_id IS NULL) AND (subscription_revision IS NULL) AND (stripe_invoice_id IS NULL) AND (promo_grant_id IS NOT NULL))));
